// How many of Richard's messages to me I have not read yet (DBU-07): the count on the Messages tab.
// DBU-08: every learner page asks this from the shell, so it is also where a visit is noticed:
// it stamps the account's lastSeenAt (at most every 10 minutes), which ends "gone quiet" in the inbox.
(async () => {
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const rows = await Noodl.Records.query('Message', { learner: { equalTo: me } }, { limit: 1000, plain: true });
    Outputs.unread = rows.filter((m) => m.author !== me && !m.readAt).length;
    try {
      const users = await Noodl.Records.query('_User', { objectId: { equalTo: me } }, { limit: 2, plain: true });
      const seen = users[0] ? Date.parse(users[0].lastSeenAt || '') : NaN;
      if (users[0] && !(Date.now() - seen < 10 * 60000)) {
        await Noodl.Records.save(me, { lastSeenAt: new Date().toISOString() }, { className: '_User' });
      }
    } catch (e) {
      console.error('[dbu:myUnread] lastSeenAt not stamped: ' + String((e && e.message) || e));
    }
    Outputs.done();
  } catch (e) {
    console.error('[dbu:myUnread]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
